-- Oscar Patel exercise encyclopedia, part 1 of 2: the activities.
--
-- 78 catalog activities compiled on 2026-10-25 from Oscar Patel's public teaching (his website and YouTube, plus a third-party
-- community document that could only be previewed). 56 are active, self-guided activities with steps, safety notes and
-- contraindications. 22 are research-only: is_active = false, described as retained source material and not available as a
-- self-guided activity (forceful palate, gum, tongue or cranial pressure, deep psoas pressure, small objects between the lips,
-- towel tongue pulling, barefoot sprinting, facial taping). Evidence is limited, and none of it is medical advice.
--
-- Rows are copied from Staging, where they were written by hand on 2026-10-25, so applying this there changes nothing.
-- Idempotent: an activity whose id already exists is left alone (curated edits and images are never overwritten). Images are
-- not part of this change. Part 2 (20261026160100) adds the draft protocol that uses these activities.

insert into public.catalog_activities (
  id, name, category, subcategory, domain, type, verb, lane_subcategory, is_active, intensity, description, duration_minutes, default_duration_min, steps, instructions, safety_notes, contraindications, benefits, health_benefits, tags, body_parts, equipment_needed, equipment, recommended_duration, recommended_frequency, recommended_intensity, tips, url, is_group, is_prenatal, target_gender, target_age_min, target_age_max, sort_order, created_at, updated_at
)
select r.id, r.name, r.category, r.subcategory, r.domain, r.type, r.verb, r.lane_subcategory, r.is_active, r.intensity, r.description, r.duration_minutes, r.default_duration_min, r.steps, r.instructions, r.safety_notes, r.contraindications, r.benefits, r.health_benefits, r.tags, r.body_parts, r.equipment_needed, r.equipment, r.recommended_duration, r.recommended_frequency, r.recommended_intensity, r.tips, r.url, r.is_group, r.is_prenatal, r.target_gender, r.target_age_min, r.target_age_max, r.sort_order, now(), now()
