{"id":"activity_oscar_4_6_breathing","name":"4–6 Breathing","category":"Breathwork","subcategory":"Breathwork","domain":"wellness","type":"canonical","verb":"Breathe","lane_subcategory":"Breathwork","is_active":true,"intensity":"low","description":"Breathing in for 4 seconds and out for 6.","duration_minutes":3,"default_duration_min":3,"steps":[{"order":1,"title":"Sit comfortably","instruction":"Sit upright with relaxed shoulders."},{"order":2,"title":"Breathe in for 4","instruction":"Breathe in through the nose for 4 seconds."},{"order":3,"title":"Breathe out for 6","instruction":"Breathe out slowly for 6 seconds."},{"order":4,"title":"Repeat comfortably","instruction":"Repeat at an easy pace without strain."}],"instructions":"1. Sit upright with relaxed shoulders.\n2. Breathe in through the nose for 4 seconds.\n3. Breathe out slowly for 6 seconds.\n4. Repeat at an easy pace without strain.","safety_notes":"Never strain; shorten the counts if you feel breathless or dizzy.","contraindications":["Asthma, heart or lung conditions: ask your clinician first","Pregnancy (avoid breath-holds)","Dizziness or fainting while practising"],"benefits":{"primary":"Slows the breath with a longer breath out","secondary":["Calm"]},"health_benefits":["Slows the breath with a longer breath out","Calm"],"tags":["oscar patel","breathing","4-6"],"body_parts":["nose","diaphragm","mouth"],"recommended_duration":"No verified count; a few minutes is typical","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":375},
{"id":"activity_oscar_adam_s_apple_elevation","name":"Adam's apple elevation","category":"Recovery","domain":"grooming","verb":"Practice","lane_subcategory":"Jaw exercises","is_active":false,"intensity":"low","description":"Touching the front of the neck, swallowing and observing the larynx rise, retained as research-only source material and not enabled for self-guided use.","duration_minutes":1,"default_duration_min":1,"safety_notes":"Not available as a self-guided activity. Requires dental or orthodontic review before any implementation. Left to a speech-language pathologist or myofunctional therapist to teach, because it involves deliberately manipulating swallowing and palpating the front of the neck.","contraindications":["Under 18","Dental work or orthodontics","TMJ symptoms","Oral injury or infection","Recent facial surgery"],"tags":["oscar patel","swallow","research-only"],"body_parts":["neck","throat"],"recommended_duration":"5 reps","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; nothing here is a recommendation to try it.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":343},
{"id":"activity_oscar_alternate_nostril_breathing","name":"Alternate Nostril Breathing","category":"Breathwork","subcategory":"Breathwork","domain":"wellness","type":"canonical","verb":"Breathe","lane_subcategory":"Breathwork","is_active":true,"intensity":"low","description":"Slow breathing that alternates between the two nostrils.","duration_minutes":4,"default_duration_min":4,"steps":[{"order":1,"title":"Sit tall","instruction":"Sit upright and relaxed."},{"order":2,"title":"Close the right nostril","instruction":"Gently close the right nostril with your thumb."},{"order":3,"title":"Breathe in left","instruction":"Breathe in slowly through the left nostril."},{"order":4,"title":"Switch and breathe out","instruction":"Close the left nostril, release the right and breathe out slowly through it."},{"order":5,"title":"Reverse","instruction":"Breathe in through the right, then out through the left. Continue in this way."}],"instructions":"1. Sit upright and relaxed.\n2. Gently close the right nostril with your thumb.\n3. Breathe in slowly through the left nostril.\n4. Close the left nostril, release the right and breathe out slowly through it.\n5. Breathe in through the right, then out through the left. Continue in this way.","safety_notes":"Keep the breath gentle and unforced. Stop if you feel dizzy or your nose is blocked.","contraindications":["Asthma, heart or lung conditions: ask your clinician first","Pregnancy (avoid breath-holds)","Dizziness or fainting while practising","Blocked nose"],"benefits":{"primary":"Slow, balanced nasal breathing","secondary":["Calm and focus"]},"health_benefits":["Slow, balanced nasal breathing","Calm and focus"],"tags":["oscar patel","breathing","pranayama","nostril"],"body_parts":["nose","diaphragm","mouth"],"recommended_duration":"2–5 minutes","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":372},
{"id":"activity_oscar_back_of_neck_isometric_press","name":"Back-of-Neck Isometric Press","category":"Strength","subcategory":"Neck","domain":"fitness","type":"canonical","verb":"Press","lane_subcategory":"Strength","is_active":true,"intensity":"low","description":"Pressing the back of the head into the hands without moving the neck.","duration_minutes":3,"default_duration_min":3,"steps":[{"order":1,"title":"Sit tall","instruction":"Sit or stand upright."},{"order":2,"title":"Hands behind the head","instruction":"Place both hands at the back of your head."},{"order":3,"title":"Press back without moving","instruction":"Press the head gently backward into your hands without letting it move."},{"order":4,"title":"Hold and relax","instruction":"Hold for about 10 seconds, then relax."}],"instructions":"1. Sit or stand upright.\n2. Place both hands at the back of your head.\n3. Press the head gently backward into your hands without letting it move.\n4. Hold for about 10 seconds, then relax.","safety_notes":"Use gentle effort. Do not use weighted neck extension or end-range loading.","contraindications":["Neck or arm pain, numbness or tingling","Dizziness, visual changes or faintness with neck movement","Recent neck injury or surgery","Known cervical spine or blood-vessel conditions"],"benefits":{"primary":"Strengthens the muscles at the back of the neck with no movement","secondary":["Posture support"]},"health_benefits":["Strengthens the muscles at the back of the neck with no movement","Posture support"],"tags":["oscar patel","neck","posterior","isometric"],"body_parts":["neck","cervical_spine","scalenes"],"recommended_duration":"Archive: 3 × 15–30 reps (face-down bench version); beginner form here is a 10-second isometric press","recommended_frequency":"3–4 sessions a week","recommended_intensity":"Comfortable and pain-free","tips":"Low-load deep neck flexor training has trial evidence for neck pain (systematic review linked). Heavier neck loading is not covered here. Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6263552/","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":367},
{"id":"activity_oscar_back_third_tongue_elevation","name":"Back-Third Tongue Elevation","category":"Recovery","subcategory":"Tongue and swallowing","domain":"grooming","type":"canonical","verb":"Practice","lane_subcategory":"Jaw exercises","is_active":true,"intensity":"low","description":"Gently lifting the back of the tongue toward the palate.","duration_minutes":1,"default_duration_min":1,"steps":[{"order":1,"title":"Sit comfortably","instruction":"Sit upright with a relaxed jaw."},{"order":2,"title":"Lift the back","instruction":"Gently raise the back of the tongue toward the palate."},{"order":3,"title":"Keep the airway open","instruction":"Make sure you can still breathe freely through the nose."},{"order":4,"title":"Relax","instruction":"Release and breathe."}],"instructions":"1. Sit upright with a relaxed jaw.\n2. Gently raise the back of the tongue toward the palate.\n3. Make sure you can still breathe freely through the nose.\n4. Release and breathe.","safety_notes":"Never block your breathing. Stop at any gagging, tightness or throat discomfort.","contraindications":["Dental work, braces or jaw (TMJ) pain: check with your dentist first","Difficulty swallowing or a choking risk","Oral injury, ulcers or infection","Under 18 unless a clinician has prescribed it","Gag reflex or throat tightness"],"benefits":{"primary":"Trains the back of the tongue","secondary":["Palate contact"]},"health_benefits":["Trains the back of the tongue","Palate contact"],"tags":["oscar patel","myofunctional","tongue","tongue"],"body_parts":["mouth","tongue","jaw","lips"],"recommended_duration":"Not specified","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Tongue and swallowing exercises taught by a clinician have trial evidence for sleep apnea (systematic review linked); the claim that tongue posture reshapes adult facial bone is not supported by good evidence. Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC11793941/","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":341},
{"id":"activity_oscar_backward_nasal_breathing_cue","name":"Backward Nasal Breathing Cue","category":"Breathwork","subcategory":"Breathwork","domain":"wellness","type":"canonical","verb":"Breathe","lane_subcategory":"Breathwork","is_active":true,"intensity":"low","description":"A mental cue for quiet nasal breathing that does not lift the shoulders.","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Breathe through the nose","instruction":"Breathe gently through your nose."},{"order":2,"title":"Imagine the direction","instruction":"Imagine the air travelling backward toward your throat rather than up into your shoulders."},{"order":3,"title":"Keep the shoulders down","instruction":"Do not lift your shoulders or chest."}],"instructions":"1. Breathe gently through your nose.\n2. Imagine the air travelling backward toward your throat rather than up into your shoulders.\n3. Do not lift your shoulders or chest.","safety_notes":"Keep it gentle; this is only a thinking cue, not extra effort.","contraindications":["Asthma, heart or lung conditions: ask your clinician first","Pregnancy (avoid breath-holds)","Dizziness or fainting while practising"],"benefits":{"primary":"Quiet nasal breathing awareness","secondary":["Relaxed shoulders"]},"health_benefits":["Quiet nasal breathing awareness","Relaxed shoulders"],"tags":["oscar patel","breathing","nasal","cue"],"body_parts":["nose","diaphragm","mouth"],"recommended_duration":"No fixed count","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":374},
{"id":"activity_oscar_barefoot_sprinting","name":"Barefoot sprinting","category":"Recovery","domain":"grooming","verb":"Sprint","lane_subcategory":"Jaw exercises","is_active":false,"intensity":"low","description":"Mentioned by Oscar without a complete, verified progression, retained as research-only source material and not enabled for self-guided use.","duration_minutes":3,"default_duration_min":3,"safety_notes":"Not available as a self-guided activity. Requires dental or orthodontic review before any implementation. No safe, verified progression is available. Sprinting barefoot, especially without gradual build-up, carries a real risk of foot, calf and Achilles injury. Sprint Intervals and Walking exist in the catalog as safer options.","contraindications":["Under 18","Dental work or orthodontics","TMJ symptoms","Oral injury or infection","Recent facial surgery"],"tags":["oscar patel","sprint","research-only"],"body_parts":["legs","feet"],"tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; nothing here is a recommendation to try it.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":334},
{"id":"activity_oscar_body_scan_and_gentle_tapping","name":"Body Scan and Gentle Tapping","category":"Mindfulness","subcategory":"Body awareness","domain":"wellness","type":"canonical","verb":"Scan","lane_subcategory":"Meditation","is_active":true,"intensity":"low","description":"A slow scan of the body with gentle tapping.","duration_minutes":7,"default_duration_min":7,"steps":[{"order":1,"title":"Settle","instruction":"Lie or sit comfortably and relax."},{"order":2,"title":"Scan from feet to face","instruction":"Notice tension from your feet up to your face."},{"order":3,"title":"Tap gently","instruction":"Gently tap your jaw, chest, shoulders and hips with your fingertips."},{"order":4,"title":"Return to natural breathing","instruction":"Let your breathing settle naturally."}],"instructions":"1. Lie or sit comfortably and relax.\n2. Notice tension from your feet up to your face.\n3. Gently tap your jaw, chest, shoulders and hips with your fingertips.\n4. Let your breathing settle naturally.","safety_notes":"Tap lightly; skip any area that is sore or injured.","contraindications":["Asthma, heart or lung conditions: ask your clinician first","Pregnancy (avoid breath-holds)","Dizziness or fainting while practising"],"benefits":{"primary":"Releases tension and settles the nervous system","secondary":["Body awareness"]},"health_benefits":["Releases tension and settles the nervous system","Body awareness"],"tags":["oscar patel","breathing","body scan","tapping"],"body_parts":["nose","diaphragm","mouth"],"recommended_duration":"5–10 minutes","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":378},
