{"id":"activity_oscar_gargling","name":"Gargling","category":"Breathwork","subcategory":"Breathwork","domain":"wellness","type":"canonical","verb":"Gargle","lane_subcategory":"Breathwork","is_active":true,"intensity":"low","description":"A brief water gargle.","duration_minutes":1,"default_duration_min":1,"steps":[{"order":1,"title":"Take a comfortable sip","instruction":"Take a comfortable mouthful of water."},{"order":2,"title":"Gargle briefly","instruction":"Tip your head back slightly and gargle for a short time."},{"order":3,"title":"Spit out","instruction":"Spit the water out."}],"instructions":"1. Take a comfortable mouthful of water.\n2. Tip your head back slightly and gargle for a short time.\n3. Spit the water out.","safety_notes":"Take small sips; never swallow if you cough or choke. Stop if the throat is sore or irritated.","contraindications":["Asthma, heart or lung conditions: ask your clinician first","Pregnancy (avoid breath-holds)","Dizziness or fainting while practising","Difficulty swallowing"],"benefits":{"primary":"Engages the muscles at the back of the throat","secondary":["Throat refresh"]},"health_benefits":["Engages the muscles at the back of the throat","Throat refresh"],"tags":["oscar patel","breathing","gargle"],"body_parts":["nose","diaphragm","mouth"],"equipment_needed":["water"],"equipment":["water"],"recommended_duration":"Not specified","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":377},
{"id":"activity_oscar_glute_release","name":"Glute Release","category":"Recovery","subcategory":"Self-myofascial release","domain":"fitness","type":"canonical","verb":"Roll","lane_subcategory":"Rest","is_active":true,"intensity":"low","description":"Small, slow movements on a ball or roller across the glute muscles.","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Sit on a ball or roller","instruction":"Sit on the ball or roller and lean toward one hip."},{"order":2,"title":"Make small movements","instruction":"Make small, slow movements across the glute muscles."},{"order":3,"title":"Change side","instruction":"Repeat on the other hip."}],"instructions":"1. Sit on the ball or roller and lean toward one hip.\n2. Make small, slow movements across the glute muscles.\n3. Repeat on the other hip.","safety_notes":"Use light-to-moderate pressure, never directly on a joint or bone. Move slowly and stop if it is sharply painful.","contraindications":["Blood clot or circulation problems, or taking blood thinners, unless your clinician has cleared it","Open wounds, bruising, rash or skin infection at the spot","Sharp, shooting or nerve-type pain (stop; use a lighter touch or skip it)"],"benefits":{"primary":"Eases tension in the area before stretching and strengthening","secondary":["Body awareness","Short, easy recovery habit"]},"health_benefits":["Eases tension in the area before stretching and strengthening","Body awareness","Short, easy recovery habit"],"tags":["oscar patel","fascia","self-massage"],"body_parts":["glutes"],"equipment_needed":["ball or foam roller"],"equipment":["ball or foam roller"],"recommended_duration":"30 seconds per side","recommended_frequency":"Daily or as needed","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":310},
{"id":"activity_oscar_hamstring_release","name":"Hamstring Release","category":"Recovery","subcategory":"Self-myofascial release","domain":"fitness","type":"canonical","verb":"Roll","lane_subcategory":"Rest","is_active":true,"intensity":"low","description":"Rolling the back of the thigh, from above the knee to the glute fold.","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Sit on the roller","instruction":"Sit with the roller under your thigh and support yourself with your hands."},{"order":2,"title":"Roll","instruction":"Roll from just above the knee toward the glute fold, avoiding the back of the knee."},{"order":3,"title":"Switch","instruction":"Repeat with the other leg."}],"instructions":"1. Sit with the roller under your thigh and support yourself with your hands.\n2. Roll from just above the knee toward the glute fold, avoiding the back of the knee.\n3. Repeat with the other leg.","safety_notes":"Use light-to-moderate pressure, never directly on a joint or bone. Move slowly and stop if it is sharply painful.","contraindications":["Blood clot or circulation problems, or taking blood thinners, unless your clinician has cleared it","Open wounds, bruising, rash or skin infection at the spot","Sharp, shooting or nerve-type pain (stop; use a lighter touch or skip it)"],"benefits":{"primary":"Eases tension in the area before stretching and strengthening","secondary":["Body awareness","Short, easy recovery habit"]},"health_benefits":["Eases tension in the area before stretching and strengthening","Body awareness","Short, easy recovery habit"],"tags":["oscar patel","fascia","self-massage"],"body_parts":["hamstrings"],"equipment_needed":["ball or foam roller"],"equipment":["ball or foam roller"],"recommended_duration":"30 seconds per side","recommended_frequency":"Daily or as needed","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":309},
{"id":"activity_oscar_hands_free_fascia_pulling_twist","name":"Hands-Free Fascia-Pulling Twist","category":"Fitness","subcategory":"Warm-up and movement","domain":"fitness","type":"canonical","verb":"Twist","lane_subcategory":"Yoga","is_active":true,"intensity":"low","description":"The whole-body twist from Oscar's current website, done hands-free. The thumb-on-palate version is kept separately as research-only (#82).","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Find the lunge","instruction":"Step into a lunge with your weight over the front knee and the back heel lifted."},{"order":2,"title":"Relax and breathe","instruction":"Relax your face and breathe quietly through the nose. Keep your hands free (no thumbs in the mouth)."},{"order":3,"title":"Rotate in order","instruction":"Slowly turn your head first, then your spine, then your hips, within a comfortable range."},{"order":4,"title":"Let the heel turn","instruction":"Let the back heel pivot outward naturally as the body turns."},{"order":5,"title":"Change sides","instruction":"Return to centre, then repeat on the other side."}],"instructions":"1. Step into a lunge with your weight over the front knee and the back heel lifted.\n2. Relax your face and breathe quietly through the nose. Keep your hands free (no thumbs in the mouth).\n3. Slowly turn your head first, then your spine, then your hips, within a comfortable range.\n4. Let the back heel pivot outward naturally as the body turns.\n5. Return to centre, then repeat on the other side.","safety_notes":"Hands-free version of Oscar's fascia-pulling twist. Do not twist the neck hard, and never combine it with palate pressure. Release rather than force.","contraindications":["Acute injury, or pain that sharpens with the movement","Dizziness or balance problems (use a wall or chair for support)","Recent surgery, unless your clinician has cleared it"],"benefits":{"primary":"A slow head-to-hips rotation from a lunge","secondary":["Spinal and hip rotation","Calm, nasal breathing"]},"health_benefits":["A slow head-to-hips rotation from a lunge","Spinal and hip rotation","Calm, nasal breathing"],"tags":["oscar patel","fascia","twist","lunge"],"body_parts":["full_body","spine","hip_flexors","obliques"],"recommended_duration":"A few slow turns each side; Oscar gives no verified total count","recommended_frequency":"Daily, as the finish of a session","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":304},
{"id":"activity_oscar_humming","name":"Humming","category":"Breathwork","subcategory":"Breathwork","domain":"wellness","type":"canonical","verb":"Hum","lane_subcategory":"Breathwork","is_active":true,"intensity":"low","description":"A gentle hum on the breath out.","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Breathe in","instruction":"Breathe in normally through the nose."},{"order":2,"title":"Hum on the breath out","instruction":"Hum gently as you breathe out."},{"order":3,"title":"Rest","instruction":"Rest for a breath or two."},{"order":4,"title":"Repeat","instruction":"Repeat a few times."}],"instructions":"1. Breathe in normally through the nose.\n2. Hum gently as you breathe out.\n3. Rest for a breath or two.\n4. Repeat a few times.","safety_notes":"Keep the hum gentle; stop if you feel light-headed.","contraindications":["Asthma, heart or lung conditions: ask your clinician first","Pregnancy (avoid breath-holds)","Dizziness or fainting while practising"],"benefits":{"primary":"Slow breath out with gentle vibration","secondary":["Relaxation"]},"health_benefits":["Slow breath out with gentle vibration","Relaxation"],"tags":["oscar patel","breathing","humming"],"body_parts":["nose","diaphragm","mouth"],"recommended_duration":"Not specified","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":376},
