{"id":"activity_oscar_narrow_gait_practice","name":"Narrow-Gait Practice","category":"Fitness","subcategory":"Posture and gait","domain":"fitness","type":"canonical","verb":"Walk","lane_subcategory":"Walking","is_active":true,"intensity":"low","description":"Walking with controlled foot placement at a natural width.","duration_minutes":3,"default_duration_min":3,"steps":[{"order":1,"title":"Stand tall","instruction":"Stand tall with your weight even through both feet."},{"order":2,"title":"Comfortable step width","instruction":"Walk with a normal, comfortable step width. Do not force your feet into a single line."},{"order":3,"title":"Place the feet with control","instruction":"Place each foot deliberately, keeping the knees soft."},{"order":4,"title":"Stay relaxed","instruction":"Keep your shoulders, jaw and breathing relaxed."}],"instructions":"1. Stand tall with your weight even through both feet.\n2. Walk with a normal, comfortable step width. Do not force your feet into a single line.\n3. Place each foot deliberately, keeping the knees soft.\n4. Keep your shoulders, jaw and breathing relaxed.","safety_notes":"Do not force a tightrope-style line; stay within a natural, stable stride.","contraindications":["Acute injury, or pain that sharpens with the movement","Dizziness or balance problems (use a wall or chair for support)","Recent surgery, unless your clinician has cleared it"],"benefits":{"primary":"Builds controlled, balanced foot placement","secondary":["Hip stability","Gait awareness"]},"health_benefits":["Builds controlled, balanced foot placement","Hip stability","Gait awareness"],"tags":["oscar patel","gait","balance"],"body_parts":["legs","glutes","core"],"recommended_duration":"Not specified by Oscar; 2–3 minutes is a comfortable start","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":332},
