{"id":"activity_oscar_neck_and_shoulder_retraction","name":"Neck and Shoulder Retraction","category":"Stretch","subcategory":"Posture","domain":"fitness","type":"canonical","verb":"Retract","lane_subcategory":"Yoga","is_active":true,"intensity":"low","description":"Gliding the head back while drawing the shoulder blades back and down.","duration_minutes":1,"default_duration_min":1,"steps":[{"order":1,"title":"Sit or stand tall","instruction":"Sit or stand upright with your eyes level."},{"order":2,"title":"Glide the head back","instruction":"Glide your head straight back without tipping the chin down."},{"order":3,"title":"Set the shoulder blades","instruction":"Draw your shoulder blades gently back and down."},{"order":4,"title":"Release","instruction":"Let go and breathe."}],"instructions":"1. Sit or stand upright with your eyes level.\n2. Glide your head straight back without tipping the chin down.\n3. Draw your shoulder blades gently back and down.\n4. Let go and breathe.","safety_notes":"Keep the movement small and pain-free.","contraindications":["Neck or arm pain, numbness or tingling","Dizziness, visual changes or faintness with neck movement","Recent neck injury or surgery","Known cervical spine or blood-vessel conditions"],"benefits":{"primary":"Resets the head and shoulders over the trunk","secondary":["Upper-back activation","Less forward-head posture"]},"health_benefits":["Resets the head and shoulders over the trunk","Upper-back activation","Less forward-head posture"],"tags":["oscar patel","posture","neck"],"body_parts":["neck","upper_trapezius","rhomboids","shoulders"],"recommended_duration":"30–60 seconds","recommended_frequency":"Daily, several times","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"i