{"id":"activity_oscar_neck_isometrics","name":"Neck Isometrics","category":"Strength","subcategory":"Neck","domain":"fitness","type":"canonical","verb":"Press","lane_subcategory":"Strength","is_active":true,"intensity":"low","description":"Gentle isometric presses forward, backward and sideways.","duration_minutes":4,"default_duration_min":4,"steps":[{"order":1,"title":"Sit tall","instruction":"Sit or stand upright with relaxed shoulders."},{"order":2,"title":"Choose a direction","instruction":"Place a hand on your forehead, the back of your head or the side of your head."},{"order":3,"title":"Press without moving","instruction":"Press gently into the hand without the head actually moving."},{"order":4,"title":"Hold","instruction":"Hold for about 10 seconds."},{"order":5,"title":"Relax and repeat","instruction":"Relax, then try the other directions."}],"instructions":"1. Sit or stand upright with relaxed shoulders.\n2. Place a hand on your forehead, the back of your head or the side of your head.\n3. Press gently into the hand without the head actually moving.\n4. Hold for about 10 seconds.\n5. Relax, then try the other directions.","safety_notes":"Gentle effort only; stop at any tingling, dizziness or arm symptoms.","contraindications":["Neck or arm pain, numbness or tingling","Dizziness, visual changes or faintness with neck movement","Recent neck injury or surgery","Known cervical spine or blood-vessel conditions"],"benefits":{"primary":"Safe, static neck strengthening in all directions","secondary":["Neck stability"]},"health_benefits":["Safe, static neck strengthening in all directions","Neck stability"],"tags":["oscar patel","neck","isometric"],"body_parts":["neck","cervical_spine","scalenes"],"recommended_duration":"10-second holds","recommended_frequency":"3–4 sessions a week","recommended_intensity":"Comfortable and pain-free","tips":"Low-load deep neck flexor training has trial evidence for neck pain (systematic review linked). Heavier neck loading is not 