{"id":"activity_oscar_suboccipital_release","name":"Suboccipital Release","category":"Recovery","subcategory":"Self-myofascial release","domain":"fitness","type":"canonical","verb":"Roll","lane_subcategory":"Rest","is_active":true,"intensity":"low","description":"Light fingertip massage under the base of the skull.","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Lie supported","instruction":"Lie on your back with your head supported on a pillow."},{"order":2,"title":"Place your fingertips","instruction":"Rest your fingertips under the back of your skull, where the neck meets it."},{"order":3,"title":"Light motions","instruction":"Use small, light massage motions, without pressing on the bones of the spine."},{"order":4,"title":"Relax","instruction":"Let your head and jaw soften."}],"instructions":"1. Lie on your back with your head supported on a pillow.\n2. Rest your fingertips under the back of your skull, where the neck meets it.\n3. Use small, light massage motions, without pressing on the bones of the spine.\n4. Let your head and jaw soften.","safety_notes":"Use light-to-moderate pressure, never directly on a joint or bone. Move slowly and stop if it is sharply painful.","contraindications":["Blood clot or circulation problems, or taking blood thinners, unless your clinician has cleared it","Open wounds, bruising, rash or skin infection at the spot","Sharp, shooting or nerve-type pain (stop; use a lighter touch or skip it)","Neck or arm pain, numbness or tingling","Dizziness, visual changes or faintness with neck movement","Recent neck injury or surgery","Known cervical spine or blood-vessel conditions"],"benefits":{"primary":"Eases tension in the area before stretching and strengthening","secondary":["Body awareness","Short, easy recovery habit"]},"health_benefits":["Eases tension in the area before stretching and strengthening","Body awareness","Short, easy recovery habit"],"tags":["oscar patel","fascia","self-massage","neck"],"body_parts":["neck","cervical_spine"],"equipment_needed":["ball or foam roller"],"equipment":["ball or foam roller"],"recommended_duration":"60 seconds","recommended_frequency":"Daily or as needed","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":316},
{"id":"activity_oscar_suction_mewing","name":"Suction Mewing","category":"Recovery","subcategory":"Tongue and swallowing","domain":"grooming","type":"canonical","verb":"Practice","lane_subcategory":"Jaw exercises","is_active":true,"intensity":"low","description":"Letting a light suction hold the tongue against the palate after a swallow.","duration_minutes":1,"default_duration_min":1,"steps":[{"order":1,"title":"Close the lips","instruction":"Close your lips gently."},{"order":2,"title":"Swallow saliva","instruction":"Swallow your saliva naturally."},{"order":3,"title":"Notice the contact","instruction":"Notice how the tongue lightly touches the palate."},{"order":4,"title":"Keep gentle suction","instruction":"Hold a comfortable, light suction without pushing hard."},{"order":5,"title":"Breathe and relax","instruction":"Keep breathing normally and stop if it is uncomfortable."}],"instructions":"1. Close your lips gently.\n2. Swallow your saliva naturally.\n3. Notice how the tongue lightly touches the palate.\n4. Hold a comfortable, light suction without pushing hard.\n5. Keep breathing normally and stop if it is uncomfortable.","safety_notes":"Never push or force. Stop if the jaw, ears or teeth ache.","contraindications":["Dental work, braces or jaw (TMJ) pain: check with your dentist first","Difficulty swallowing or a choking risk","Oral injury, ulcers or infection","Under 18 unless a clinician has prescribed it"],"benefits":{"primary":"Helps you feel where the tongue rests","secondary":["Light suction awareness"]},"health_benefits":["Helps you feel where the tongue rests","Light suction awareness"],"tags":["oscar patel","myofunctional","tongue","mewing","suction"],"body_parts":["mouth","tongue","jaw","lips"],"recommended_duration":"No fixed count","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Tongue and swallowing exercises taught by a clinician have trial evidence for sleep apnea (systematic review linked); the claim 