{"id":"activity_oscar_supported_neck_flexion_chin_nods","name":"Supported Neck Flexion (Chin Nods)","category":"Strength","subcategory":"Neck","domain":"fitness","type":"canonical","verb":"Nod","lane_subcategory":"Strength","is_active":true,"intensity":"low","description":"Small, supported chin nods to train the muscles at the front of the neck.","duration_minutes":3,"default_duration_min":3,"steps":[{"order":1,"title":"Lie supported","instruction":"Lie on your back with your head fully supported on a pillow."},{"order":2,"title":"Nod the chin","instruction":"Make a small, gentle nodding movement, bringing your chin toward your throat."},{"order":3,"title":"Hold briefly","instruction":"Hold for about 3 seconds."},{"order":4,"title":"Return slowly","instruction":"Let the head settle back under control."}],"instructions":"1. Lie on your back with your head fully supported on a pillow.\n2. Make a small, gentle nodding movement, bringing your chin toward your throat.\n3. Hold for about 3 seconds.\n4. Let the head settle back under control.","safety_notes":"Keep the head supported. Do not hang the head off a bench, add hand resistance or weight, or force the range.","contraindications":["Neck or arm pain, numbness or tingling","Dizziness, visual changes or faintness with neck movement","Recent neck injury or surgery","Known cervical spine or blood-vessel conditions"],"benefits":{"primary":"Trains the deep muscles at the front of the neck","secondary":["Better head control"]},"health_benefits":["Trains the deep muscles at the front of the neck","Better head control"],"tags":["oscar patel","neck","flexion","chin nod"],"body_parts":["neck","cervical_spine","scalenes"],"recommended_duration":"Oscar's archive lists 3 sets of 15–30 reps with 3-second holds; this beginner form uses small supported nods and no resistance","recommended_frequency":"3–4 sessions a week","recommended_intensity":"Comfortable and pain-free","tips":"Low-load deep neck flexor training has trial evidence for neck pain (systematic review linked). Heavier neck loading is not covered here. Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","url":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6263552/","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":365},
{"id":"activity_oscar_temporalis_massage","name":"Temporalis Massage","category":"Recovery","subcategory":"Facial muscles","domain":"grooming","type":"canonical","verb":"Massage","lane_subcategory":"Jaw exercises","is_active":true,"intensity":"low","description":"Slow fingertip circles on the temples and above the ears.","duration_minutes":2,"default_duration_min":2,"steps":[{"order":1,"title":"Place your fingertips","instruction":"Place your fingertips on your temples."},{"order":2,"title":"Slow circles","instruction":"Make slow circles above the ears."},{"order":3,"title":"Relax the jaw","instruction":"Let the jaw hang loose."}],"instructions":"1. Place your fingertips on your temples.\n2. Make slow circles above the ears.\n3. Let the jaw hang loose.","safety_notes":"Use gentle pressure; stop if it triggers a headache.","contraindications":["Skin infection, acne flare or open wounds in the area","Recent facial surgery, fillers or injectables","Eye conditions: never press on the eyeball","Recent head injury"],"benefits":{"primary":"Releases tension in the temple muscle","secondary":["Jaw relaxation"]},"health_benefits":["Releases tension in the temple muscle","Jaw relaxation"],"tags":["oscar patel","face","facial muscles","temporalis"],"body_parts":["face","jaw","cheeks"],"equipment_needed":["clean hands"],"equipment":["clean hands"],"recommended_duration":"60 seconds","recommended_frequency":"Daily","recommended_intensity":"Comfortable and pain-free","tips":"Described in Oscar Patel's public materials as compiled on 25 October 2026 from his website, videos, social posts and an unverified community document; the steps are a practical adaptation, not word-for-word instructions.","is_group":false,"is_prenatal":false,"target_gender":["all"],"target_age_min":18,"sort_order":357},
